import re
from auto_config.generator.bts.managed_object_generic import ManagedObjectGeneric


class ManagedObject(ManagedObjectGeneric):

    @property
    def is_mo_ecpri(self):
        tnl_id = self.tnl_id
        if tnl_id and tnl_id >= 2:
            return True
        return any(x in self.dist_name for x in ['SYNC-2', 'TNL-2', 'SYNC-3'])

    @property
    def tnl_id(self):
        srch = re.search(r"TNL-(\d+)", self.dist_name)
        if srch:
            return int(srch.group(1))
        return None
